examples.template:
Column(
    modifier = Modifier.fillMaxWidth(),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.Title, heading = true)
        MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
    }
    MonarchSearchBar(
        query = query,
        onQueryChange = { query = it },
        onSearch = {},
        modifier = Modifier.fillMaxWidth(),
        placeholder = {{search}},
    )
    val words = query.lowercase().split(" ").filter { it.isNotBlank() }
    val matches = articles.filter { (_, title, category) ->
        words.all { "$title $category".lowercase().contains(it) }
    }
    Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        matches.groupBy { it.third }.forEach { (category, list) ->
            MonarchText(text = category, style = MonarchTextStyle.Subheading, heading = true)
            list.forEach { (id, title, _) ->
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(min = 40.dp)
                        .clickable { /* Open the article id. */ },
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchIcon(SampleIcons.Document, contentDescription = null, size = MonarchIconSize.Sm)
                    MonarchText(text = title)
                }
            }
        }
    }
    MonarchButton(
        text = {{contact}},
        onClick = { /* Open the contact form. */ },
        variant = MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Sm,
    )
}

